    private Object nullable(EditText field){String value=field.getText().toString().trim();return value.isEmpty()?JSONObject.NULL:Integer.parseInt(value);}
    private int required(EditText field){Object value=nullable(field);if(value==JSONObject.NULL)throw new IllegalArgumentException("请填写必需数值");return (Integer)value;}
