    private int watchedSlot=-1;private void watchDateChanges(){watchedSlot=original.optInt("game_slot",-1);Runnable changed=()->{if(restoringDraft)return;try{int current=GameDate.slot(required(month),required(day),phase.getSelectedItemPosition()==1);if(current==watchedSlot)return;watchedSlot=current;currentCapacity.setSelection(0);towerEntry.setSelection(0);for(Link link:links.values()){if(link.preparationTiming!=null)link.preparationTiming.setSelection(0);for(Map.Entry<String,Spinner> flag:link.preparationFlags.entrySet())if(flag.getKey().startsWith("current.")||flag.getKey().startsWith("calendar.")||flag.getKey().equals("observedIntroductionAvailable"))flag.getValue().setSelection(0);}}catch(Exception ignored){}};android.text.TextWatcher watcher=new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){changed.run();}public void afterTextChanged(android.text.Editable e){}};month.addTextChangedListener(watcher);day.addTextChangedListener(watcher);phase.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int n,long id){changed.run();}});}
    public void organizeSections(){watchDateChanges();List<View> views=new ArrayList<>();for(int i=0;i<getChildCount();i++)views.add(getChildAt(i));removeAllViews();LinearLayout section=null;int index=0;for(View view:views){String text=view instanceof TextView?((TextView)view).getText().toString():"";if(Arrays.asList("当前实际状态","塔与阶段次数","可见社交属性","社群目标与当前状态").contains(text)){index++;final LinearLayout body=new LinearLayout(getContext());body.setOrientation(VERTICAL);body.setPadding(12,4,12,18);body.setVisibility(index==1?VISIBLE:GONE);Button heading=new Button(getContext());heading.setAllCaps(false);heading.setText(index+" · "+text+"  ▾");heading.setTextColor(0xff06263e);heading.setBackgroundTintList(ColorStateList.valueOf(0xff9bdbff));heading.setOnClickListener(v->body.setVisibility(body.getVisibility()==VISIBLE?GONE:VISIBLE));addView(heading);addView(body);section=body;}else if(section!=null)section.addView(view);else addView(view);}}
    private String identityLabel(String slug,String fallback){try(java.io.InputStream input=getContext().getAssets().open("planner_v2/social_goal_identity_labels.json")){java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();byte[] buffer=new byte[4096];int read;while((read=input.read(buffer))!=-1)bytes.write(buffer,0,read);JSONArray entities=new JSONObject(bytes.toString("UTF-8")).getJSONArray("entities");for(int i=0;i<entities.length();i++){JSONObject entry=entities.getJSONObject(i);if(entry.getString("entityId").equals("p3r.social_link."+slug))return entry.getString("selectorLabelZhHans");}}catch(Exception ignored){}return fallback;}
    private boolean restoringDraft;private int draftStageIndex=-1;
    private List<View> draftInputs(){List<View> out=new ArrayList<>();gatherInputs(this,out);return out;}
    private static void gatherInputs(View view,List<View> out){if(view instanceof EditText||view instanceof Spinner||view instanceof CheckBox){out.add(view);return;}if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++)gatherInputs(group.getChildAt(i),out);}}
    public void setInputsEnabled(boolean enabled){for(View input:draftInputs())input.setEnabled(enabled);}
    public JSONObject exportDraft()throws JSONException{JSONArray values=new JSONArray();StringBuilder schema=new StringBuilder("2:");for(View view:draftInputs()){if(view instanceof EditText){schema.append("E,");values.put(((EditText)view).getText().toString());}else if(view instanceof Spinner){Spinner input=(Spinner)view;schema.append("S").append(input.getCount()).append(',');values.put(input.getSelectedItemPosition());}else{schema.append("C,");values.put(((CheckBox)view).isChecked());}}return new JSONObject().put("schema",schema.toString()).put("values",values);}
    public boolean restoreDraft(JSONObject draft)throws JSONException{if(!exportDraft().getString("schema").equals(draft.optString("schema")))return false;List<View> inputs=draftInputs();JSONArray values=draft.getJSONArray("values");if(values.length()!=inputs.size())return false;restoringDraft=true;try{for(int i=0;i<inputs.size();i++){View view=inputs.get(i);if(view instanceof EditText)((EditText)view).setText(values.getString(i));else if(view instanceof Spinner){if(view==stage)draftStageIndex=values.getInt(i);((Spinner)view).setSelection(values.getInt(i));}else ((CheckBox)view).setChecked(values.getBoolean(i));}}finally{try{watchedSlot=GameDate.slot(required(month),required(day),phase.getSelectedItemPosition()==1);}catch(Exception ignored){}restoringDraft=false;}return true;}
    public void observeDraftChanges(Runnable callback){for(View view:draftInputs()){if(view instanceof EditText)((EditText)view).addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){if(!restoringDraft)callback.run();}public void afterTextChanged(android.text.Editable e){}});else if(view instanceof Spinner){Spinner input=(Spinner)view;AdapterView.OnItemSelectedListener previous=input.getOnItemSelectedListener();input.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){if(previous!=null)previous.onNothingSelected(p);}public void onItemSelected(AdapterView<?> p,View v,int n,long id){if(previous!=null&&!restoringDraft)previous.onItemSelected(p,v,n,id);if(!restoringDraft)callback.run();}});}else ((CheckBox)view).setOnCheckedChangeListener((button,checked)->{if(!restoringDraft)callback.run();});}}

